import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.DtFGJNng.js";const c=JSON.parse('{"title":"Tim dan Git","description":"","frontmatter":{},"headers":[],"relativePath":"tim-dan-git.md","filePath":"tim-dan-git.md","lastUpdated":1794463556000}'),d={name:"tim-dan-git.md"};function r(o,a,s,l,u,m){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="tim-dan-git" tabindex="-1">Tim dan Git <a class="header-anchor" href="#tim-dan-git" aria-label="Permalink to &quot;Tim dan Git&quot;">​</a></h1><p>deuz tidak menggantikan branch, pull request, atau code review. Ia hanya mencatat satu hal yang tidak dicatat Git: <strong>siapa sudah menyatakan sebuah dokumen siap.</strong> Halaman ini menunjukkan cara memadukan keduanya.</p><h2 id="di-mana-work-tinggal" tabindex="-1">Di mana work tinggal <a class="header-anchor" href="#di-mana-work-tinggal" aria-label="Permalink to &quot;Di mana work tinggal&quot;">​</a></h2><p>Folder <code>deuz/</code> ada di repository yang sama dengan kodenya, jadi work ikut di-commit seperti file lain. Untuk sekarang deuz mendukung satu repository. Spec dan kode berada di tempat yang sama.</p><h2 id="pola-yang-disarankan" tabindex="-1">Pola yang disarankan <a class="header-anchor" href="#pola-yang-disarankan" aria-label="Permalink to &quot;Pola yang disarankan&quot;">​</a></h2><h3 id="fase-perencanaan-satu-branch-dokumen" tabindex="-1">Fase perencanaan: satu branch dokumen <a class="header-anchor" href="#fase-perencanaan-satu-branch-dokumen" aria-label="Permalink to &quot;Fase perencanaan: satu branch dokumen&quot;">​</a></h3><ol><li>Analyst membuat branch untuk work, misalnya <code>docs/pemesanan-buku</code>.</li><li><code>proposal.md</code> dan <code>specs/</code> ditulis di branch itu, lalu dibuka pull request <strong>khusus dokumen</strong>.</li><li>Review dilakukan di PR, dengan komentar per baris. Persetujuan bisnis dicatat analyst setelah rapat.</li><li>Setelah pemilik mengonfirmasi (<code>/deuz:ready</code>), file <code>.deuz.yaml</code> ikut berubah. Commit perubahan itu bersama dokumennya.</li></ol><p>Designer dan backend/frontend bisa melanjutkan di branch yang sama, atau membuka PR dokumen sendiri untuk <code>ui-design</code> dan <code>api-contract</code> setelah PR sebelumnya di-merge.</p><h3 id="fase-implementasi-branch-per-peran" tabindex="-1">Fase implementasi: branch per peran <a class="header-anchor" href="#fase-implementasi-branch-per-peran" aria-label="Permalink to &quot;Fase implementasi: branch per peran&quot;">​</a></h3><p>Setelah <code>api-contract</code> disepakati, backend, frontend, dan QA bekerja paralel, masing-masing di branch kodenya sendiri. Setiap PR kode:</p><ul><li>menyertakan perubahan <code>tasks-&lt;peran&gt;.md</code> (task yang dicentang);</li><li>menyertakan promote yang menjadi tugas peran itu, misalnya kontrak yang diterjemahkan ke file OpenAPI di PR backend, atau file desain yang disalin ke home desain di PR frontend. Konten masuk ke home <strong>bersama</strong> kode yang mengimplementasikannya.</li></ul><h3 id="penutup-archive" tabindex="-1">Penutup: archive <a class="header-anchor" href="#penutup-archive" aria-label="Permalink to &quot;Penutup: archive&quot;">​</a></h3><p>Setelah semua PR di-merge, satu PR kecil berisi hasil <code>/deuz:archive</code>: delta yang digabung ke <code>deuz/specs/</code> dan work yang dipindah ke <code>work/archive/</code>.</p><h2 id="review-dan-konfirmasi" tabindex="-1">Review dan konfirmasi <a class="header-anchor" href="#review-dan-konfirmasi" aria-label="Permalink to &quot;Review dan konfirmasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Tempatnya</th><th>Yang dicatat</th></tr></thead><tbody><tr><td><strong>Review isi</strong></td><td>Pull request dan diskusi</td><td>Komentar, usulan perubahan</td></tr><tr><td><strong>Konfirmasi &quot;siap&quot;</strong></td><td><code>/deuz:ready</code> → <code>.deuz.yaml</code></td><td>Peran yang menyatakan siap, dan hash isi saat itu</td></tr></tbody></table><p>deuz sengaja tidak memodelkan reviewer. Review sudah ditangani PR, dan menambahkan status review di deuz hanya menambah birokrasi.</p><h2 id="konflik-di-deuz-yaml" tabindex="-1">Konflik di <code>.deuz.yaml</code> <a class="header-anchor" href="#konflik-di-deuz-yaml" aria-label="Permalink to &quot;Konflik di `.deuz.yaml`&quot;">​</a></h2><p><code>.deuz.yaml</code> adalah file teks biasa, jadi bisa bentrok kalau dua branch mengonfirmasi artifact berbeda di waktu yang sama. Cara mengatasinya:</p><ol><li>Selesaikan konflik dengan mengambil salah satu versi.</li><li>Jalankan <code>deuz status --write</code>. deuz menghitung ulang status dari isi file dan menulis ulang <code>.deuz.yaml</code> tanpa mengubah konfirmasi yang tercatat.</li><li>Kalau ada konfirmasi yang hilang karena konflik, pemiliknya cukup menjalankan <code>/deuz:ready</code> lagi.</li></ol><h2 id="dari-solo-ke-tim" tabindex="-1">Dari solo ke tim <a class="header-anchor" href="#dari-solo-ke-tim" aria-label="Permalink to &quot;Dari solo ke tim&quot;">​</a></h2><p>Work yang dimulai satu orang (yang mengonfirmasi semua peran sekaligus) bisa diserahkan ke tim tanpa konversi:</p><ul><li>Konfirmasi yang sudah ada tetap berlaku.</li><li>Kalau anggota tim mengubah dokumen, hash membuatnya kembali <code>draft</code>, dan pemilik perannya yang mengonfirmasi ulang.</li><li><code>/deuz:status</code> menunjukkan siapa yang sedang ditunggu, memakai nama peran dari <code>config.yaml</code>.</li></ul>',22)])])}const h=e(d,[["render",r]]);export{c as __pageData,h as default};
